const slots = [];
const start = new Date();
start.setHours(9, 0, 0, 0);
const end = new Date();
end.setHours(17, 0, 0, 0);
while (start < end) {
  slots.push(new Date(start));
  start.setMinutes(start.getMinutes() + 30);
}
return slots.map(slot => ({ json: { time: slot.toISOString() } }));
